<?php
require dirname(__DIR__).'/includes/bootstrap.php';require_permission('drivers.export');header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="drivers-'.date('Y-m-d').'.csv"');$out=fopen('php://output','w');fputcsv($out,['Driver ID','Name','Phone','Status','Verification','Source','Registration UTC']);foreach(db()->query('SELECT driver_code,full_name,phone,status,verification_status,registration_source,registration_at FROM drivers ORDER BY registration_at DESC') as $r){$safe=array_map(fn($v)=>is_string($v)&&preg_match('/^[=+\-@]/',$v)?"'".$v:$v,$r);fputcsv($out,$safe);}fclose($out);exit;
